import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}
/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}
/**
 * Private row → domain mappers for the repository layer.
 *
 * SQLite stores branded ids as plain text and collections as JSON strings, so
 * exactly one place is allowed to re-apply the brands and parse the JSON: here.
 * Services never see a `*Row` type.
 */
import type {
  ActivityEventRow,
  AttachmentRow,
  CommentRow,
  InvitationRow,
  InvoiceRow,
  IssueRow,
  LabelRow,
  MemberRow,
  NotificationPreferenceRow,
