sub(p, """export async function updateProject(""", """/**
 * Starts a new project from an existing one, optionally with its issues.
 *
 * Gated like a creation: the actor needs `project:read` on the (live) source
 * and `project:create` in the workspace, the project quota applies, and the
 * per-project issue quota applies to the whole batch of copies. All of that is
 * checked before anything is written, so a refused clone leaves nothing behind.
 *
 * The copies are a fresh start (see `projectRepo.insertProjectClone`): live
 * issues only, in the workspace's default status, unassigned and authored by
 * the actor, renumbered from 1. Because the clone publishes `project.cloned`
 * instead of `project.created` and one `issue.created` per copy, the search
 * index and the usage meters those would have driven are updated here.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const toCopy = input.includeIssues
    ? await issueRepo.listLiveIssuesForClone(input.orgId, source.id)
    : [];
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, toCopy.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key} ` +
        `(limit ${getLimit(org.plan, "issuesPerProject")}); ` +
        `cloning would create ${toCopy.length}`,
    );
  }

  const { project, issues } = await projectRepo.insertProjectClone(
    source,
    {
      name: input.name,
      slug: input.slug,
      key: input.key,
      issueStatus: org.settings.defaultIssueStatus,
      authorId: actor.userId,
    },
    toCopy,
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: issues.length,
  });

  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: issues.length,
  });
  await indexProject(input.orgId, project);
  for (const issue of issues) {
    await indexIssue(input.orgId, issue);
  }

  return project;
}

export async function updateProject(""")
