import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { IsoTimestamp, LabelId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Project } from "@/types/project";

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function cloneInput(
  tenant: Tenant,
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: "Platform, again",
    slug: "platform-again",
    key: "PLA2",
    includeIssues: true,
    ...overrides,
  };
}

/** Inserts an issue straight through the repository, bypassing the quota. */
async function seedIssue(
  tenant: Tenant,
  overrides: Partial<{ title: string; labelIds: LabelId[] }> = {},
): Promise<Issue> {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    {
      ...issueInput(tenant.org.id, tenant.project.id, { title: overrides.title ?? "Seeded" }),
      labelIds: overrides.labelIds ?? [],
    },
    tenant.userIds.owner,
    number,
  );
}

async function issuesOf(tenant: Tenant, project: Project): Promise<readonly Issue[]> {
  const page = await issueRepo.listIssues({
    orgId: tenant.org.id,
    projectId: project.id,
    includeArchived: true,
    limit: 100,
    cursor: null,
  });
  return [...page.items].sort((a, b) => a.number - b.number);
}

describe("services/project-service cloneProject", () => {
  it("creates a project of the same workspace with the caller's name, slug and key", async () => {
    const tenant = await createTenant("clonebasic", "growth");

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect(clone.id).not.toBe(tenant.project.id);
    expect(clone).toMatchObject({
      orgId: tenant.org.id,
      name: "Platform, again",
      slug: "platform-again",
      key: "PLA2",
      archivedAt: null,
    });
    await expect(projectRepo.findProjectById(tenant.org.id, clone.id)).resolves.toEqual(clone);
  });

  it("copies description, visibility, colour and lead, and resets status and dates", async () => {
    const tenant = await createTenant("clonereset", "growth");
    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      description: "The release train",
      visibility: "private",
      status: "paused",
      color: "#ff0000",
      targetDate: "2030-01-01T00:00:00.000Z" as IsoTimestamp,
    });

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect(clone).toMatchObject({
      description: "The release train",
      visibility: "private",
      leadId: tenant.userIds.owner,
      color: "#ff0000",
      status: "active",
      startsAt: null,
      targetDate: null,
      archivedAt: null,
    });
  });

  it("makes a taken slug unique by suffix, like a created project", async () => {
    const tenant = await createTenant("cloneslug", "growth");

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { slug: "platform" }),
    );

    expect(clone.slug).toBe("platform-2");
  });

  it("copies live issues as a fresh start and renumbers them from 1", async () => {
    const tenant = await createTenant("cloneissues", "growth");
    const org = tenant.org.id;
    const label = await labelRepo.insertLabel({
      orgId: org,
      name: "bug",
      color: "#ff0000",
      description: null,
    });

    const first = await issueRepo.insertIssue(
      {
        ...issueInput(org, tenant.project.id, { title: "First", dueAt: "2031-05-05T00:00:00.000Z" }),
        description: "Do it",
        priority: "high",
        estimate: 5,
        labelIds: [label.id],
      },
      tenant.userIds.owner,
      3,
    );
    await issueRepo.setIssueAssignee(org, first.id, tenant.userIds.admin);
    await issueRepo.setIssueStatus(org, first.id, "in_progress");
    await issueRepo.setIssueStatus(org, first.id, "done");

    const archived = await issueRepo.insertIssue(
      issueInput(org, tenant.project.id, { title: "Archived" }),
      tenant.userIds.owner,
      5,
    );
    await issueRepo.archiveIssue(org, archived.id);

    await issueRepo.insertIssue(
      issueInput(org, tenant.project.id, { title: "Second" }),
      tenant.userIds.owner,
      9,
    );

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));
    const copies = await issuesOf(tenant, clone);

    expect(copies.map((issue) => [issue.number, issue.title])).toEqual([
      [1, "First"],
      [2, "Second"],
    ]);
    expect(copies[0]).toMatchObject({
      projectId: clone.id,
      description: "Do it",
      priority: "high",
      estimate: 5,
      dueAt: "2031-05-05T00:00:00.000Z",
      labelIds: [label.id],
      status: "backlog",
      assigneeId: null,
      authorId: tenant.userIds.member,
      startedAt: null,
      completedAt: null,
      parentId: null,
      archivedAt: null,
    });
    expect(copies[0]?.id).not.toBe(first.id);

    // Issues created in the clone afterwards continue after the copies.
    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(org, clone.id, { title: "Third" }),
    );
    expect(next.number).toBe(3);
  });

  it("starts the copies in the workspace's default issue status", async () => {
    const tenant = await createTenant("clonedefault", "growth");
    await seedIssue(tenant);
    const { getDb } = await import("@/server/db");
    getDb().$client
      .prepare("UPDATE organizations SET default_issue_status = 'todo' WHERE id = ?")
      .run(tenant.org.id);

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect((await issuesOf(tenant, clone)).map((issue) => issue.status)).toEqual(["todo"]);
  });

  it("walks every live issue of the source, not just a page", async () => {
    const tenant = await createTenant("clonebig", "growth");
    for (let i = 0; i < 130; i += 1) await seedIssue(tenant, { title: `Issue ${i}` });

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect(await issueRepo.countIssues(tenant.org.id, clone.id)).toBe(130);
    const numbers = (await issueRepo.listLiveIssuesForClone(tenant.org.id, clone.id)).map(
      (issue) => issue.number,
    );
    expect(numbers[0]).toBe(1);
    expect(numbers.at(-1)).toBe(130);
  });

  it("copies no issues when includeIssues is false", async () => {
    const tenant = await createTenant("clonebare", "growth");
    await seedIssue(tenant);
    const seen = capture("project.cloned");

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { includeIssues: false }),
    );

    expect(await issueRepo.countIssues(tenant.org.id, clone.id, { includeArchived: true })).toBe(0);
    expect(seen[0]).toMatchObject({ issuesCopied: 0 });
  });

  it("never copies comments or attachments, and leaves the source untouched", async () => {
    const tenant = await createTenant("clonecomments", "growth");
    const issue = await seedIssue(tenant, { title: "Talked about" });
    await commentRepo.insertComment(
      {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "a conversation",
        parentId: null,
        mentionedUserIds: [],
      },
      tenant.userIds.member,
    );
    await attachmentRepo.insertAttachment(tenant.org.id, issue.id, tenant.userIds.member, {
      filename: "spec.pdf",
      contentType: "application/pdf",
      sizeBytes: 10,
    } as never);
    const sourceBefore = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    const issuesBefore = await issuesOf(tenant, tenant.project);

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));
    const [copy] = await issuesOf(tenant, clone);

    expect(copy).toBeDefined();
    expect(await commentRepo.countComments(tenant.org.id, copy!.id)).toBe(0);
    expect(await attachmentRepo.listAttachments(tenant.org.id, copy!.id)).toHaveLength(0);
    expect(await projectRepo.findProjectById(tenant.org.id, tenant.project.id)).toEqual(
      sourceBefore,
    );
    expect(await issuesOf(tenant, tenant.project)).toEqual(issuesBefore);
    expect(await commentRepo.countComments(tenant.org.id, issue.id)).toBe(1);
  });

  it("publishes exactly one project.cloned on behalf of the actor, and no creation events", async () => {
    const tenant = await createTenant("cloneevents", "growth");
    await seedIssue(tenant);
    await seedIssue(tenant);
    const cloned = capture("project.cloned");
    const createdProjects = capture("project.created");
    const createdIssues = capture("issue.created");

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect(cloned).toHaveLength(1);
    expect(cloned[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: clone.id,
      sourceProjectId: tenant.project.id,
      issuesCopied: 2,
    });
    expect(createdProjects).toHaveLength(0);
    expect(createdIssues).toHaveLength(0);
  });

  it("records one audit entry under the new project", async () => {
    const tenant = await createTenant("cloneaudit", "growth");
    await seedIssue(tenant);

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    const page = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["project.cloned"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "project.cloned",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: clone.id,
      projectId: clone.id,
      metadata: { sourceProjectId: tenant.project.id, issuesCopied: 1 },
    });
  });

  it("makes the clone and its issues searchable and moves the usage meters at once", async () => {
    const tenant = await createTenant("clonemeters", "growth");
    await seedIssue(tenant, { title: "Zebra crossing" });
    await seedIssue(tenant, { title: "Zebra stripes" });
    const before = await usageRepo.getUsage(tenant.org.id);

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { name: "Giraffe program" }),
    );

    const issues = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Zebra",
      kinds: ["issue"],
      projectId: clone.id,
      limit: 25,
      cursor: null,
    });
    expect(issues.items).toHaveLength(2);

    const projects = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Giraffe",
      kinds: ["project"],
      limit: 25,
      cursor: null,
    });
    expect(projects.items.map((row) => row.subjectId)).toEqual([clone.id]);

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.projectsUsed).toBe(before.projectsUsed + 1);
    expect(after.issuesUsed).toBe(before.issuesUsed + 2);
  });

  describe("gates", () => {
    it("needs the permission to create a project", async () => {
      const tenant = await createTenant("clonedenied", "growth");
      const cloned = capture("project.cloned");

      await expect(
        projectService.cloneProject(tenant.actors.viewer, cloneInput(tenant)),
      ).rejects.toBeInstanceOf(PermissionDeniedError);

      expect(cloned).toHaveLength(0);
      expect(await projectRepo.countProjects(tenant.org.id)).toBe(1);
    });

